// API @jinx-ui/react здесь принят по соглашению (value/onChange, options);
// имена пропсов стоит сверить с docs/components.md перед коммитом.
import { useCallback, useId, useState } from 'react';
import { Button, Select, Slider, Switch } from '@jinx-ui/react';

export type ThemeMode = 'brutal' | 'glass' | 'minimal';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const DEFAULTS: AppearanceSettings = {
  theme: 'brutal',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

const THEMES: ReadonlyArray<{ value: ThemeMode; label: string }> = [
  { value: 'brutal', label: 'Brutal' },
  { value: 'glass', label: 'Glass' },
  { value: 'minimal', label: 'Minimal' },
];

const FONTS: ReadonlyArray<{ value: string; label: string }> = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const SCALE_MIN = 80;
const SCALE_MAX = 140;

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...DEFAULTS,
    ...defaultValue,
  });

  const update = useCallback(
    (patch: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const next = { ...prev, ...patch };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const themeGroupId = useId();
  const scaleId = useId();
  const denseId = useId();
  const fontId = useId();

  const activeTheme = THEMES.find((t) => t.value === settings.theme) ?? THEMES[0];

  return (
    <section
      className="jx-card jx-stack"
      style={{ gap: 'var(--jx-space-5)', padding: 'var(--jx-space-5)' }}
      aria-labelledby={`${themeGroupId}-title`}
    >
      <header
        className="jx-row"
        style={{ alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}
      >
        <h2 id={`${themeGroupId}-title`} className="jx-heading">
          Внешний вид
        </h2>
        <span className="jx-badge" aria-live="polite">
          Тема: {activeTheme.label}
        </span>
      </header>

      <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <span className="jx-label" id={`${themeGroupId}-label`}>
          Тема оформления
        </span>
        <div
          className="jx-segmented"
          role="radiogroup"
          aria-labelledby={`${themeGroupId}-label`}
        >
          {THEMES.map((theme) => {
            const selected = theme.value === settings.theme;
            return (
              <Button
                key={theme.value}
                role="radio"
                aria-checked={selected}
                tabIndex={selected ? 0 : -1}
                variant={selected ? 'primary' : 'ghost'}
                size="sm"
                onClick={() => update({ theme: theme.value })}
              >
                {theme.label}
              </Button>
            );
          })}
        </div>
      </div>

      <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <div
          className="jx-row"
          style={{ alignItems: 'baseline', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}
        >
          <label className="jx-label" htmlFor={scaleId}>
            Масштаб интерфейса
          </label>
          <span className="jx-hint" aria-live="polite">
            {settings.scale}%
          </span>
        </div>
        <Slider
          id={scaleId}
          min={SCALE_MIN}
          max={SCALE_MAX}
          step={5}
          value={settings.scale}
          aria-valuetext={`${settings.scale} процентов`}
          onChange={(scale: number) => update({ scale })}
        />
      </div>

      <div
        className="jx-field jx-row"
        style={{ alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}
      >
        <div className="jx-stack" style={{ gap: 'var(--jx-space-1)' }}>
          <label className="jx-label" htmlFor={denseId}>
            Плотная вёрстка
          </label>
          <span className="jx-hint">Уменьшает отступы и высоту строк</span>
        </div>
        <Switch
          id={denseId}
          checked={settings.dense}
          onChange={(dense: boolean) => update({ dense })}
        />
      </div>

      <hr className="jx-divider" />

      <div className="jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
        <h3 className="jx-heading">Ещё</h3>
        <div className="jx-field jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
          <label className="jx-label" htmlFor={fontId}>
            Шрифт
          </label>
          <Select
            id={fontId}
            value={settings.fontFamily}
            options={FONTS}
            onChange={(fontFamily: string) => update({ fontFamily })}
          />
        </div>
      </div>
    </section>
  );
}

